    deepExplanation: "Step 1 — Understand the requirement.\n\nStep 1 — Count frequencies and maintain the top k with a small min-heap.\n\nWITHOUT BUILT-IN / CORE:\n```ts\ninterface HeapItem {\n  value: number;\n  count: number;\n}\n\nclass MinHeap {\n  private readonly items: HeapItem[] = [];\n\n  push(item: HeapItem): void {\n    this.items.push(item);\n    this.up();\n  }\n\n  pop(): HeapItem | undefined {\n    if (this.items.length === 0) return undefined;\n    if (this.items.length === 1) return this.items.pop();\n\n    const root = this.items[0]!;\n    this.items[0] = this.items.pop()!;\n    this.down();\n    return root;\n  }\n\n  peek(): HeapItem | undefined {\n    return this.items[0];\n  }\n\n  get size(): number {\n    return this.items.length;\n  }\n\n  private up(): void {\n    let index = this.items.length - 1;\n\n    while (index > 0) {\n      const parent = Math.floor((index - 1) / 2);\n      if (this.items[parent]!.count <= this.items[index]!.count) break;\n      [this.items[parent], this.items[index]] = [this.items[index]!, this.items[parent]!];\n      index = parent;\n    }\n  }\n\n  private down(): void {\n    let index = 0;\n\n    while (true) {\n      const left = index * 2 + 1;\n      const right = index * 2 + 2;\n      let smallest = index;\n\n      if (left < this.items.length && this.items[left]!.count < this.items[smallest]!.count) {\n        smallest = left;\n      }\n\n      if (right < this.items.length && this.items[right]!.count < this.items[smallest]!.count) {\n        smallest = right;\n      }\n\n      if (smallest === index) break;\n      [this.items[index], this.items[smallest]] = [this.items[smallest]!, this.items[index]!];\n      index = smallest;\n    }\n  }\n}\n\nfunction topKFrequent(nums: readonly number[], k: number): number[] {\n  const counts = new Map<number, number>();\n\n  for (const value of nums) {\n    counts.set(value, (counts.get(value) ?? 0) + 1);\n  }\n\n  const heap = new MinHeap();\n\n  for (const [value, count] of counts) {\n    heap.push({ value, count });\n\n    if (heap.size > k) heap.pop();\n  }\n\n  const result: number[] = [];\n\n  while (heap.size > 0) {\n    result.push(heap.pop()!.value);\n  }\n\n  return result.reverse();\n}\n```\n\nWITH BUILT-IN:\n```ts\nfunction topKFrequentUsingSort(\n  nums: readonly number[],\n  k: number,\n): number[] {\n  const counts = new Map<number, number>();\n\n  for (const value of nums) {\n    counts.set(value, (counts.get(value) ?? 0) + 1);\n  }\n\n  return [...counts.entries()]\n    .sort((a, b) => b[1] - a[1])\n    .slice(0, k)\n    .map(([value]) => value);\n}\n```\n\nStep 2 — Example:\n[1,1,1,2,2,3], k=2\n→ [1,2]\n\nStep 3 — Complexity:\nHeap: O(n log k) after O(n) counting.\nSort baseline: O(n log n) over distinct values.\nSpace: O(n) for frequency map plus O(k) heap.\n\nStep 5 — Interview takeaway:\nChoose correctness first, then optimize only the actual bottleneck.",
